mapper.sql:
FROM pms_poi p WHERE p.camp_id = #{campId} AND p.status = 1 AND p.is_deleted = 0
AND p.is_availability = #{isAvailability}
AND EXISTS ( SELECT 1 FROM channel_poi_rel rel JOIN channel_account ca ON ca.account_id = rel.account_id AND ca.camp_id = rel.camp_id WHERE rel.camp_id = p.camp_id AND rel.poi_id = p.poi_id AND ca.channel_id = #{channelId} )
